{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "A closely related 2-methyltryptamine amide showed an in vivo mouse brain-to-plasma ratio of 0.5 and was labeled BBB-permeable, demonstrating that this tryptamine scaffold can confer meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Another 2-methyltryptamine-containing compound showed an in vivo mouse brain-to-plasma ratio of 0.4 with good penetration, supporting CNS access for the shared tryptamine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A 2-methyltryptamine analogue with a brain-to-plasma ratio of 0.16 was still classified as BBB-permeable, indicating that even lower ratios in this series are considered meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Belinostat, a cinnamohydroxamate HDAC inhibitor, showed limited CSF penetration in non-human primates (<10% of free plasma exposure), highlighting a potential hydroxamate-related CNS liability; however, the query adds a basic tryptamine amine that is absent in belinostat and is associated with brain penetration in the higher-similarity analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query combines a cinnamohydroxamate warhead with a 2-methyltryptamine basic amine. The most transferable experimental evidence comes from 2-methyltryptamine analogues with measurable in vivo brain-to-plasma ratios (0.16-0.5) classified as permeable/good penetration, outweighing the poorer CSF penetration seen for belinostat, which lacks the basic tryptamine moiety. Overall, the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain or CSF exposure measurement for the exact query molecule is present in the provided records.",
    "Efflux-transporter status of the query is not directly assessed; hydroxamate-containing compounds can be transporter substrates.",
    "The belinostat CSF data come from a different chemotype without the basic tryptamine group, limiting direct transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

